package com.example

/**
 * Grade 10 History Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and provides distinct question variations across papers 1 to 30.
 */
object HistoryGrade10QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 10 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..6 -> "ඓතිහාසික මූලාශ්‍ර - සාහිත්‍ය මූලාශ්‍ර" to run {
        val list = listOf(
          Quad("ලංකාවේ දැනට හමුවී ඇති පැරණිතම පද්‍යමය වංසකතාව වන්නේ කුමක්ද?", listOf("දීපවංසය", "මහාවංසය", "චූලවංසය", "බෝධිවංසය"), 1, "ක්‍රි.ව. 4 වන සියවසේදී පාලි භාෂාවෙන් රචිත දීපවංසය මෙරට පැරණිතම වංසකතාවයි."),
          Quad("මහාවිහාරික මහානාම හිමියන් විසින් 5 වන සියවසේදී සම්පාදනය කළ ඓතිහාසික ග්‍රන්ථය කුමක්ද?", listOf("මහාවංසය", "දීපවංසය", "ථූපවංසය", "පූජාවලිය"), 1, "මහානාම හිමියන් සීහලට්ඨකථා මහාවංසය ඇසුරින් මහාවංසය පාලි පද්‍යයෙන් රචනා කළහ."),
          Quad("දුටුගැමුණු රජු රුවන්වැලි මහා සෑය ඉදිකිරීමේ පුවත විස්තරාත්මකව සඳහන් වන ඓතිහාසික මූලාශ්‍රය කුමක්ද?", listOf("ථූපවංසය", "බෝධිවංසය", "ධාතුවංසය", "දළදාවංසය"), 1, "පරාක්‍රම පණ්ඩිතයන් විසින් රචිත ථූපවංසයේ රුවන්වැලිසෑයේ ඉතිහාසය විස්තර කෙරේ."),
          Quad("ශ්‍රී මහා බෝධීන් වහන්සේ ලක්දිවට වැඩමවීම සහ රෝපණය කිරීම පිළිබඳ ලියැවුණු වංසකතාව කුමක්ද?", listOf("බෝධිවංසය (මහාබෝධිවංසය)", "ථූපවංසය", "නිකාය සංග්‍රහය", "රාජාවලිය"), 1, "විලිගම්මුල මහාතෙරුන් විසින් සිංහල බෝධිවංසය සම්පාදනය කර ඇත."),
          Quad("දඹදෙණි යුගයේ මයුරපාද පරිවේණාධිපති බුද්ධපුත්‍ර හිමියන් ලියූ ඓතිහාසික තොරතුරු ඇතුළත් කෘතිය කුමක්ද?", listOf("පූජාවලිය", "සද්ධර්මරත්නාවලිය", "නිකාය සංග්‍රහය", "රාජාවලිය"), 1, "පූජාවලිය ග්‍රන්ථයේ ලක්දිව රජවරුන් බුදුසසුනට කළ පූජෝපහාර විස්තර කෙරේ."),
          Quad("විජය කුමරුගේ පැමිණීමේ සිට දෙවන විමලධර්මසූරිය රජු දක්වා අඛණ්ඩව සිංහල රජවරුන් විස්තර කරන ග්‍රන්ථය කුමක්ද?", listOf("රාජාවලිය", "නිකාය සංග්‍රහය", "දීපවංසය", "චූලවංසය"), 1, "රාජාවලිය යනු අඛණ්ඩව ලංකා රජ පෙළපත විස්තර කරන ප්‍රධාන සිංහල සාහිත්‍ය මූලාශ්‍රයකි.")
        )
        list[(slot - 1 + v).mod(list.size)]
      }
      in 7..12 -> "ඓතිහාසික මූලාශ්‍ර - පුරාවිද්‍යා හා විදේශීය මූලාශ්‍ර" to run {
        val list = listOf(
          Quad("ශ්‍රී ලංකාවේ මුල් ඓතිහාසික යුගයට අයත් සෙල්ලිපි ලියැවී ඇති පැරණි අක්ෂර මාලාව කුමක්ද?", listOf("පූර්ව බ්‍රාහ්මී අක්ෂර", "නාගරී අක්ෂර", "දේවනාගරී අක්ෂර", "පල්ලව අක්ෂර"), 1, "ක්‍රි.පූ. 3 වන සියවසේ සිට ක්‍රි.ව. 1 වන සියවස දක්වා ලියැවුණු සෙල්ලිපි පූර්ව බ්‍රාහ්මී අක්ෂරවලින් යුක්තය."),
          Quad("ලක්දිව ලෙන් ආරාම සංඝයාට පූජා කිරීමේදී ලෙනේ කටාරමට යටින් කොටන ලද ලිපි හඳුන්වන්නේ කෙසේද?", listOf("කටාරම් ලිපි (ලෙන් ලිපි)", "ටැම් ලිපි", "පුවරු ලිපි", "ගිරි ලිපි"), 1, "වැසි ජලය ලෙන තුළට ගලා ඒම වැළැක්වීමට කෙටූ කටාරමට යටින් ලෙන් ලිපි කොටා ඇත."),
          Quad("ශ්‍රී ලංකාව 'තැප්‍රෝබේන්' (Taprobane) නමින් හඳුන්වා සිතියම් ගත කළ ග්‍රීක-රෝම භූගෝල විද්‍යාඥයා කවුද?", listOf("ක්ලෝඩියස් ටොලමි", "මෙගස්තිනීස්", "ප්ලිනි", "ස්ට්‍රාබෝ"), 1, "ක්‍රි.ව. 2 වන සියවසේදී ක්ලෝඩියස් ටොලමි ලංකාව තැප්‍රෝබේන් නමින් සිතියම් ගත කළේය."),
          Quad("ක්‍රි.ව. 5 වන සියවසේ අනුරාධපුර අභයගිරි විහාරයේ නැවතී බෞද්ධ පොතපත පිටපත් කරගත් චීන ජාතික හිමිනම කවුද?", listOf("ෆාහියන් හිමි (Fa-Hsien)", "හියුංසාං හිමි", "ඉට්සිං හිමි", "චෙන්ග් හෝ"), 1, "ෆාහියන් හිමි වසර දෙකක් අනුරාධපුරයේ ගත කරමින් බෞද්ධ සූත්‍ර පිටපත් කරගත්හ."),
          Quad("අනුරාධපුර යුගයේ මුල්ම දේශීය කාසි විශේෂය ලෙස සැලකෙන්නේ කුමක්ද?", listOf("හස්ත මුද්‍රිත කහවණු (Kahavanu)", "රන් මස්ස", "ඩොච්චිය", "තඹ කාසි"), 1, "අනුරාධපුර මුල් යුගයේ ගනුදෙනු සඳහා හස්ත මුද්‍රිත කහවණු (Punch-marked coins) භාවිත විය."),
          Quad("ක්‍රි.ව. 6 වන සියවසේ 'ක්‍රිස්තියානි ටොපොග්‍රැෆි' කෘතිය ලියමින් ලක්දිව ජාත්‍යන්තර වෙළෙඳ මධ්‍යස්ථානයක් බව පැවසූ ග්‍රීක නාවිකයා කවුද?", listOf("කොස්මස් ඉන්ඩිකොප්ලූස්ටස්", "මාකෝ පෝලෝ", "ඉබන් බතූතා", "ටොලමි"), 1, "කොස්මස් ඉන්ඩිකොප්ලූස්ටස් ලක්දිව පෙරදිග සහ අපරදිග වෙළෙඳාමේ කේන්ද්‍රස්ථානයක් ලෙස විස්තර කළේය.")
        )
        list[(slot - 7 + v).mod(list.size)]
      }
      in 13..18 -> "ප්‍රාග් ඓතිහාසික යුගය - මානවයා සහ ලෙන්" to run {
        val list = listOf(
